 $oldPath='';$oldName='';if($id){$q=$pdo->prepare('SELECT * FROM downloadable_forms WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('ফরমটি পাওয়া যায়নি।');$oldPath=$old['file_path'];$oldName=$old['original_name'];}
 [$path,$original,$mime,$size]=aspi_form_upload($_FILES['document']??[],$oldPath?:null);if($path==='')throw new RuntimeException('একটি PDF, DOC অথবা DOCX ফাইল নির্বাচন করুন।');if($original==='')$original=$oldName;if($mime===''){$mime=$old['mime_type']??'application/pdf';$size=(int)($old['file_size']??0);}if($start!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))throw new RuntimeException('শুরুর তারিখ সঠিক নয়।');if($end!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))throw new RuntimeException('শেষ তারিখ সঠিক নয়।');if($start!==''&&$end!==''&&$end<$start)throw new RuntimeException('শেষ তারিখ শুরুর তারিখের আগে হতে পারবে না।');
 $slug=$id?($old['slug']):aspi_admin_form_slug($pdo,$title);$vals=[$title,$description,$category,$path,$original,$mime,$size,$status,$showHome,$start?:null,$end?:null];
 if($id){$sql='UPDATE downloadable_forms SET title=?,description=?,category=?,file_path=?,original_name=?,mime_type=?,file_size=?,status=?,show_home=?,start_date=?,end_date=? WHERE id=?';$pdo->prepare($sql)->execute([...$vals,$id]);if($oldPath!==$path)aspi_form_remove($oldPath);$_SESSION['flash']='ফরম আপডেট হয়েছে।';}
 else{$pdo->prepare('INSERT INTO downloadable_forms(title,slug,description,category,file_path,original_name,mime_type,file_size,status,show_home,start_date,end_date) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$title,$slug,$description,$category,$path,$original,$mime,$size,$status,$showHome,$start?:null,$end?:null]);$_SESSION['flash']='নতুন ফরম সংরক্ষণ হয়েছে।';}
 header('Location: forms.php');exit;
 } catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'ফরম সংরক্ষণ করা যায়নি। ডেটাবেজ ও আপলোড অনুমতি যাচাই করুন।';}}
